// Observe the proposal actually generated by the setup form.
async function observeOnboardingProposal(page) {
  await page.evaluate(() => {
    const build = LHRFCoachAdapters.buildProgramme;
    LHRFCoachAdapters.buildProgramme = (...args) => {
      const proposal = build(...args);
      window.testOnboardingProposal = proposal;
      return proposal;
    };
  });
}
const onboardingProposal = page => page.evaluate(() => window.testOnboardingProposal);
module.exports = {observeOnboardingProposal, onboardingProposal};
